import React, { useState, useEffect } from 'react';
import { 
  Typography, 
  Grid, 
  Card, 
  CardContent, 
  CardHeader,
  TextField,
  Button,
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Paper,
  Divider,
  Chip,
  IconButton,
  CircularProgress
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import RefreshIcon from '@mui/icons-material/Refresh';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import DownloadIcon from '@mui/icons-material/Download';
import TradingChart from '../components/TradingChart';

const MarketData = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [marketData, setMarketData] = useState([]);
  const [selectedSymbol, setSelectedSymbol] = useState(null);

  // Generate mock market data
  useEffect(() => {
    generateMockData();
  }, []);

  const generateMockData = () => {
    setLoading(true);
    
    // Sample market data
    setTimeout(() => {
      const mockData = [
        { symbol: 'AAPL', name: 'Apple Inc.', price: 182.63, change: 1.24, changePercent: 0.68, volume: 58432156, marketCap: '2.87T', sector: 'Technology' },
        { symbol: 'MSFT', name: 'Microsoft Corporation', price: 405.72, change: 3.84, changePercent: 0.96, volume: 29541236, marketCap: '3.05T', sector: 'Technology' },
        { symbol: 'AMZN', name: 'Amazon.com Inc.', price: 178.12, change: -0.86, changePercent: -0.48, volume: 36985214, marketCap: '1.91T', sector: 'Consumer Cyclical' },
        { symbol: 'GOOGL', name: 'Alphabet Inc.', price: 165.83, change: 1.56, changePercent: 0.95, volume: 25142365, marketCap: '2.08T', sector: 'Communication Services' },
        { symbol: 'META', name: 'Meta Platforms Inc.', price: 485.94, change: -3.25, changePercent: -0.66, volume: 19854621, marketCap: '1.25T', sector: 'Communication Services' },
        { symbol: 'TSLA', name: 'Tesla Inc.', price: 172.63, change: -4.27, changePercent: -2.41, volume: 132568974, marketCap: '548.92B', sector: 'Automotive' },
        { symbol: 'NVDA', name: 'NVIDIA Corporation', price: 925.17, change: 15.63, changePercent: 1.72, volume: 48965321, marketCap: '2.28T', sector: 'Technology' },
        { symbol: 'JPM', name: 'JPMorgan Chase & Co.', price: 196.42, change: 2.13, changePercent: 1.10, volume: 17854632, marketCap: '565.27B', sector: 'Financial Services' },
        { symbol: 'JNJ', name: 'Johnson & Johnson', price: 148.75, change: -0.35, changePercent: -0.23, volume: 8965423, marketCap: '358.64B', sector: 'Healthcare' },
        { symbol: 'V', name: 'Visa Inc.', price: 272.36, change: 1.84, changePercent: 0.68, volume: 7854123, marketCap: '556.83B', sector: 'Financial Services' },
        { symbol: 'PG', name: 'Procter & Gamble Co.', price: 164.92, change: 0.54, changePercent: 0.33, volume: 6854213, marketCap: '387.65B', sector: 'Consumer Defensive' },
        { symbol: 'MA', name: 'Mastercard Incorporated', price: 456.18, change: 3.65, changePercent: 0.81, volume: 5784123, marketCap: '425.91B', sector: 'Financial Services' },
        { symbol: 'HD', name: 'Home Depot Inc.', price: 342.56, change: -1.27, changePercent: -0.37, volume: 4851236, marketCap: '342.96B', sector: 'Consumer Cyclical' },
        { symbol: 'UNH', name: 'UnitedHealth Group Inc.', price: 489.32, change: 2.54, changePercent: 0.52, volume: 3526984, marketCap: '452.13B', sector: 'Healthcare' },
        { symbol: 'BAC', name: 'Bank of America Corp.', price: 37.29, change: 0.42, changePercent: 1.14, volume: 42365987, marketCap: '294.15B', sector: 'Financial Services' }
      ];
      
      setMarketData(mockData);
      setLoading(false);
    }, 800);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleSearch = () => {
    // In a real app this would filter from API
    // For demo just filter the mock data
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
    }, 500);
  };

  const handleSelectSymbol = (symbol) => {
    setSelectedSymbol(symbol);
  };

  const filteredData = searchTerm 
    ? marketData.filter(item => 
        item.symbol.toLowerCase().includes(searchTerm.toLowerCase()) || 
        item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.sector.toLowerCase().includes(searchTerm.toLowerCase())
      )
    : marketData;

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Market Data
      </Typography>
      
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Card>
            <CardContent sx={{ pb: 1 }}>
              <Grid container spacing={2} alignItems="center">
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Search by Symbol, Name or Sector"
                    variant="outlined"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    InputProps={{
                      endAdornment: (
                        <IconButton onClick={handleSearch}>
                          <SearchIcon />
                        </IconButton>
                      ),
                    }}
                  />
                </Grid>
                <Grid item xs={12} md={6} sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                  <Button 
                    variant="outlined"
                    startIcon={<RefreshIcon />}
                    onClick={generateMockData}
                    sx={{ mr: 2 }}
                  >
                    Refresh
                  </Button>
                  <Button 
                    variant="outlined"
                    startIcon={<DownloadIcon />}
                  >
                    Export
                  </Button>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>
        
        {selectedSymbol && (
          <Grid item xs={12}>
            <Card>
              <CardHeader 
                title={`${selectedSymbol} Chart`}
                action={
                  <IconButton onClick={() => setSelectedSymbol(null)}>
                    <RefreshIcon />
                  </IconButton>
                }
              />
              <Divider />
              <CardContent sx={{ height: 400 }}>
                <TradingChart symbol={selectedSymbol} interval="1d" />
              </CardContent>
            </Card>
          </Grid>
        )}
        
        <Grid item xs={12}>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Symbol</TableCell>
                  <TableCell>Name</TableCell>
                  <TableCell align="right">Price</TableCell>
                  <TableCell align="right">Change</TableCell>
                  <TableCell align="right">% Change</TableCell>
                  <TableCell align="right">Volume</TableCell>
                  <TableCell>Market Cap</TableCell>
                  <TableCell>Sector</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={9} align="center" sx={{ py: 3 }}>
                      <CircularProgress size={40} />
                    </TableCell>
                  </TableRow>
                ) : (
                  filteredData
                    .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                    .map((row) => (
                      <TableRow key={row.symbol}>
                        <TableCell component="th" scope="row">
                          <Typography fontWeight="bold">{row.symbol}</Typography>
                        </TableCell>
                        <TableCell>{row.name}</TableCell>
                        <TableCell align="right">${row.price.toFixed(2)}</TableCell>
                        <TableCell 
                          align="right"
                          sx={{ 
                            color: row.change >= 0 ? 'success.main' : 'error.main',
                            fontWeight: 'bold'
                          }}
                        >
                          {row.change >= 0 ? '+' : ''}{row.change.toFixed(2)}
                        </TableCell>
                        <TableCell align="right">
                          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end' }}>
                            {row.changePercent >= 0 ? (
                              <TrendingUpIcon color="success" fontSize="small" sx={{ mr: 0.5 }} />
                            ) : (
                              <TrendingDownIcon color="error" fontSize="small" sx={{ mr: 0.5 }} />
                            )}
                            <Typography
                              sx={{ 
                                color: row.changePercent >= 0 ? 'success.main' : 'error.main',
                                fontWeight: 'bold'
                              }}
                            >
                              {row.changePercent >= 0 ? '+' : ''}{row.changePercent.toFixed(2)}%
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell align="right">{(row.volume / 1000000).toFixed(2)}M</TableCell>
                        <TableCell>{row.marketCap}</TableCell>
                        <TableCell>
                          <Chip 
                            label={row.sector} 
                            size="small" 
                            variant="outlined"
                          />
                        </TableCell>
                        <TableCell>
                          <Button 
                            variant="text" 
                            color="primary"
                            size="small"
                            onClick={() => handleSelectSymbol(row.symbol)}
                          >
                            Chart
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))
                )}
                
                {!loading && filteredData.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={9} align="center" sx={{ py: 3 }}>
                      No data found
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
            <TablePagination
              rowsPerPageOptions={[5, 10, 25]}
              component="div"
              count={filteredData.length}
              rowsPerPage={rowsPerPage}
              page={page}
              onPageChange={handleChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
            />
          </TableContainer>
        </Grid>
      </Grid>
    </div>
  );
};

export default MarketData; 