import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Snackbar, Alert } from '@mui/material';

// Notification priority levels
export const NotificationPriority = {
  HIGH: 'high',
  MEDIUM: 'medium',
  LOW: 'low'
};

// Notification groups
export const NotificationGroup = {
  TRADE: 'trade',
  SYSTEM: 'system',
  ALERT: 'alert',
  ERROR: 'error'
};

const NotificationContext = createContext();

export const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotification must be used within a NotificationProvider');
  }
  return context;
};

export const NotificationProvider = ({ children }) => {
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [settings, setSettings] = useState({
    email: true,
    sms: false,
    desktop: true,
    voice: false,
    sound: true,
    priorityLevels: {
      [NotificationPriority.HIGH]: true,
      [NotificationPriority.MEDIUM]: true,
      [NotificationPriority.LOW]: true
    },
    groups: {
      [NotificationGroup.TRADE]: true,
      [NotificationGroup.SYSTEM]: true,
      [NotificationGroup.ALERT]: true,
      [NotificationGroup.ERROR]: true
    }
  });
  const [open, setOpen] = useState(false);
  const [message, setMessage] = useState('');
  const [severity, setSeverity] = useState('info'); // 'success', 'error', 'warning', 'info'

  // Load notifications from localStorage on mount
  useEffect(() => {
    try {
      const savedNotifications = localStorage.getItem('notifications');
      if (savedNotifications) {
        const parsed = JSON.parse(savedNotifications);
        setNotifications(Array.isArray(parsed) ? parsed : []);
      }
    } catch (error) {
      console.error('Error loading notifications:', error);
      setNotifications([]);
    }
  }, []);

  // Save notifications to localStorage when they change
  useEffect(() => {
    try {
      localStorage.setItem('notifications', JSON.stringify(notifications));
    } catch (error) {
      console.error('Error saving notifications:', error);
    }
  }, [notifications]);

  const addNotification = useCallback(({
    id = Date.now(),
    message,
    type = 'info',
    priority = NotificationPriority.MEDIUM,
    group = NotificationGroup.SYSTEM,
    template = null,
    templateData = null,
    timestamp = new Date().toISOString(),
    read = false
  }) => {
    setNotifications(prev => [{
      id,
      message,
      type,
      priority,
      group,
      template,
      templateData,
      timestamp,
      read
    }, ...prev]);

    if (!read) {
      setUnreadCount(prev => prev + 1);
    }
  }, []);

  const markAsRead = useCallback((notificationId) => {
    setNotifications(prev =>
      prev.map(notification =>
        notification.id === notificationId
          ? { ...notification, read: true }
          : notification
      )
    );
    setUnreadCount(prev => Math.max(0, prev - 1));
  }, []);

  const markAllAsRead = useCallback(() => {
    setNotifications(prev =>
      prev.map(notification => ({ ...notification, read: true }))
    );
    setUnreadCount(0);
  }, []);

  const removeNotification = useCallback((notificationId) => {
    setNotifications(prev =>
      prev.filter(notification => notification.id !== notificationId)
    );
  }, []);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
    setUnreadCount(0);
  }, []);

  const updateSettings = useCallback((newSettings) => {
    setSettings(prev => ({
      ...prev,
      ...newSettings
    }));
  }, []);

  const getFilteredNotifications = useCallback(({
    priority = null,
    group = null,
    read = null,
    limit = 50
  } = {}) => {
    return notifications
      .filter(notification => {
        if (priority && notification.priority !== priority) return false;
        if (group && notification.group !== group) return false;
        if (read !== null && notification.read !== read) return false;
        return true;
      })
      .slice(0, limit);
  }, [notifications]);

  const showNotification = (message, severity = 'info') => {
    setMessage(message);
    setSeverity(severity);
    setOpen(true);
  };

  const hideNotification = (event, reason) => {
    if (reason === 'clickaway') {
      return;
    }
    setOpen(false);
  };

  const value = {
    notifications,
    unreadCount,
    settings,
    addNotification,
    markAsRead,
    markAllAsRead,
    removeNotification,
    clearNotifications,
    updateSettings,
    getFilteredNotifications,
    showSuccess: (msg) => showNotification(msg, 'success'),
    showError: (msg) => showNotification(msg, 'error'),
    showWarning: (msg) => showNotification(msg, 'warning'),
    showInfo: (msg) => showNotification(msg, 'info')
  };

  return (
    <NotificationContext.Provider value={value}>
      {children}
      <Snackbar 
        open={open} 
        autoHideDuration={6000} 
        onClose={hideNotification}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert onClose={hideNotification} severity={severity} sx={{ width: '100%' }}>
          {message}
        </Alert>
      </Snackbar>
    </NotificationContext.Provider>
  );
};

export default NotificationContext; 