import React, { useState, useRef, useEffect } from 'react';
import {
  Badge,
  IconButton,
  Menu,
  MenuItem,
  Typography,
  Box,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Chip,
  Tooltip,
  Button
} from '@mui/material';
import {
  Notifications as NotificationsIcon,
  Circle as CircleIcon,
  CheckCircle as CheckCircleIcon,
  Error as ErrorIcon,
  Warning as WarningIcon,
  Info as InfoIcon,
  Delete as DeleteIcon,
  Settings as SettingsIcon
} from '@mui/icons-material';
import { useNotification, NotificationPriority, NotificationGroup } from '../contexts/NotificationContext';
import { formatDistanceToNow } from 'date-fns';

const priorityColors = {
  [NotificationPriority.HIGH]: 'error',
  [NotificationPriority.MEDIUM]: 'warning',
  [NotificationPriority.LOW]: 'info'
};

const groupIcons = {
  [NotificationGroup.TRADE]: <CircleIcon />,
  [NotificationGroup.SYSTEM]: <InfoIcon />,
  [NotificationGroup.ALERT]: <WarningIcon />,
  [NotificationGroup.ERROR]: <ErrorIcon />
};

const NotificationBell = () => {
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedGroup, setSelectedGroup] = useState(null);
  const [selectedPriority, setSelectedPriority] = useState(null);
  const menuRef = useRef(null);
  
  const {
    notifications,
    unreadCount,
    settings,
    markAsRead,
    markAllAsRead,
    removeNotification,
    clearNotifications,
    updateSettings,
    getFilteredNotifications
  } = useNotification();

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
    setSelectedGroup(null);
    setSelectedPriority(null);
  };

  const handleNotificationClick = (notification) => {
    if (!notification.read) {
      markAsRead(notification.id);
    }
    // Handle notification click (e.g., navigate to relevant page)
  };

  const handleFilterChange = (group, priority) => {
    setSelectedGroup(group);
    setSelectedPriority(priority);
  };

  const handleClearAll = () => {
    clearNotifications();
    handleClose();
  };

  const handleMarkAllAsRead = () => {
    markAllAsRead();
  };

  const handleSettingsClick = () => {
    // Open settings dialog
  };

  const filteredNotifications = getFilteredNotifications({
    group: selectedGroup,
    priority: selectedPriority,
    limit: 50
  });

  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        handleClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <>
      <Tooltip title="Notifications">
        <IconButton
          color="inherit"
          onClick={handleClick}
          sx={{ position: 'relative' }}
        >
          <Badge badgeContent={unreadCount} color="error">
            <NotificationsIcon />
          </Badge>
        </IconButton>
      </Tooltip>

      <Menu
        ref={menuRef}
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleClose}
        PaperProps={{
          sx: {
            width: 360,
            maxHeight: 480
          }
        }}
      >
        <Box sx={{ p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Typography variant="h6">Notifications</Typography>
          <Box>
            <IconButton size="small" onClick={handleSettingsClick}>
              <SettingsIcon />
            </IconButton>
            <IconButton size="small" onClick={handleClearAll}>
              <DeleteIcon />
            </IconButton>
          </Box>
        </Box>

        <Divider />

        <Box sx={{ p: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
          {Object.values(NotificationGroup).map((group) => (
            <Chip
              key={group}
              label={group}
              size="small"
              onClick={() => handleFilterChange(group, selectedPriority)}
              color={selectedGroup === group ? 'primary' : 'default'}
              variant={selectedGroup === group ? 'filled' : 'outlined'}
            />
          ))}
          {Object.values(NotificationPriority).map((priority) => (
            <Chip
              key={priority}
              label={priority}
              size="small"
              onClick={() => handleFilterChange(selectedGroup, priority)}
              color={selectedPriority === priority ? 'primary' : 'default'}
              variant={selectedPriority === priority ? 'filled' : 'outlined'}
            />
          ))}
        </Box>

        <Divider />

        {unreadCount > 0 && (
          <Box sx={{ p: 1 }}>
            <Button
              fullWidth
              variant="outlined"
              size="small"
              onClick={handleMarkAllAsRead}
            >
              Mark all as read
            </Button>
          </Box>
        )}

        <List sx={{ p: 0 }}>
          {filteredNotifications.length > 0 ? (
            filteredNotifications.map((notification) => (
              <React.Fragment key={notification.id}>
                <ListItem
                  button
                  onClick={() => handleNotificationClick(notification)}
                  sx={{
                    bgcolor: notification.read ? 'transparent' : 'action.hover',
                    '&:hover': { bgcolor: 'action.selected' }
                  }}
                >
                  <ListItemIcon>
                    {groupIcons[notification.group]}
                  </ListItemIcon>
                  <ListItemText
                    primary={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography variant="body2" component="span">
                          {notification.message}
                        </Typography>
                        <Chip
                          label={notification.priority}
                          size="small"
                          color={priorityColors[notification.priority]}
                        />
                      </Box>
                    }
                    secondary={formatDistanceToNow(new Date(notification.timestamp), { addSuffix: true })}
                  />
                </ListItem>
                <Divider />
              </React.Fragment>
            ))
          ) : (
            <ListItem>
              <ListItemText
                primary="No notifications"
                secondary="You're all caught up!"
              />
            </ListItem>
          )}
        </List>
      </Menu>
    </>
  );
};

export default NotificationBell; 