import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import { blueGrey, deepPurple } from '@mui/material/colors';

import Dashboard from './pages/Dashboard';
import Strategies from './pages/Strategies';
import Backtester from './pages/Backtester';
import TradeHistory from './pages/TradeHistory';
import Settings from './pages/Settings';
import MarketData from './pages/MarketData';
import APIConfiguration from './pages/APIConfiguration';
import TradingViewAlerts from './pages/TradingViewAlerts';
import Layout from './components/Layout';
import AIInsights from './components/AIInsights';
import Login from './pages/Login';
import Register from './pages/Register';
import { NotificationProvider } from './contexts/NotificationContext';
import ProtectedRoute from './components/ProtectedRoute';

const theme = createTheme({
  palette: {
    mode: 'dark',
    primary: {
      main: deepPurple[400],
    },
    secondary: {
      main: blueGrey[400],
    },
    background: {
      default: '#121212',
      paper: '#1e1e1e',
    },
  },
  typography: {
    fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
    h1: {
      fontSize: '2.5rem',
    },
    h2: {
      fontSize: '2rem',
    },
  },
  components: {
    MuiAppBar: {
      defaultProps: {
        elevation: 0,
      },
      styleOverrides: {
        root: {
          backgroundColor: '#1a1a1a',
        },
      },
    },
    MuiDrawer: {
      styleOverrides: {
        paper: {
          backgroundColor: '#1a1a1a',
        },
      },
    },
  },
});

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <NotificationProvider>
        <Router>
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route path="/" element={<ProtectedRoute><Layout /></ProtectedRoute>}>
              <Route index element={<Dashboard />} />
              <Route path="strategies" element={<Strategies />} />
              <Route path="backtester" element={<Backtester />} />
              <Route path="trade-history" element={<TradeHistory />} />
              <Route path="market-data" element={<MarketData />} />
              <Route path="api-configuration" element={<APIConfiguration />} />
              <Route path="tradingview-alerts" element={<TradingViewAlerts />} />
              <Route path="ai-insights" element={<AIInsights />} />
              <Route path="settings" element={<Settings />} />
            </Route>
          </Routes>
        </Router>
      </NotificationProvider>
    </ThemeProvider>
  );
}

export default App; 