import React from 'react';
import { Navigate, Outlet } from 'react-router-dom';

const ProtectedRoute = ({ children }) => {
  // This is a simplified authentication check
  // In a real app, you would check for a valid token or session
  const isAuthenticated = true; // For demo purposes, always authenticate
  
  if (!isAuthenticated) {
    // Redirect to login if not authenticated
    return <Navigate to="/login" />;
  }
  
  // If authenticated, render the children or outlet
  return children || <Outlet />;
};

export default ProtectedRoute; 