import React, { useState } from 'react';
import { 
  Typography, 
  Grid, 
  Card, 
  CardContent, 
  CardHeader,
  TextField,
  Button,
  Box,
  Switch,
  FormControlLabel,
  Divider,
  Alert,
  IconButton,
  Chip
} from '@mui/material';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CheckIcon from '@mui/icons-material/Check';
import CancelIcon from '@mui/icons-material/Cancel';
import SaveIcon from '@mui/icons-material/Save';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';

const APIConfiguration = () => {
  const [apiEndpoints, setApiEndpoints] = useState({
    tradingViewWebhook: {
      url: 'https://your-server.com/webhook/tradingview',
      isEnabled: true,
      isConnected: true
    },
    alpaca: {
      apiKey: 'ALPACA_API_KEY_HERE',
      secretKey: '••••••••••••••••••••••••',
      isEnabled: true,
      isConnected: true
    },
    interactiveBrokers: {
      accountId: 'IB_ACCOUNT_ID_HERE',
      host: 'localhost',
      port: '4001',
      isEnabled: false,
      isConnected: false
    },
    unusualWhales: {
      apiKey: 'UNUSUAL_WHALES_API_KEY_HERE',
      isEnabled: true,
      isConnected: true
    }
  });

  const [showSecretKey, setShowSecretKey] = useState(false);
  const [copied, setCopied] = useState(null);
  const [customEndpoints, setCustomEndpoints] = useState([
    { name: 'Market Data API', url: 'https://api.marketdata.com', apiKey: 'MARKET_DATA_API_KEY', isEnabled: true }
  ]);
  const [newEndpoint, setNewEndpoint] = useState({ name: '', url: '', apiKey: '', isEnabled: true });
  const [showAddForm, setShowAddForm] = useState(false);
  
  const handleToggleEndpoint = (api) => {
    setApiEndpoints({
      ...apiEndpoints,
      [api]: {
        ...apiEndpoints[api],
        isEnabled: !apiEndpoints[api].isEnabled
      }
    });
  };

  const handleChangeApiValue = (api, field, value) => {
    setApiEndpoints({
      ...apiEndpoints,
      [api]: {
        ...apiEndpoints[api],
        [field]: value
      }
    });
  };

  const handleCopyToClipboard = (text, field) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopied(field);
      setTimeout(() => setCopied(null), 2000);
    });
  };

  const handleAddCustomEndpoint = () => {
    if (newEndpoint.name && newEndpoint.url) {
      setCustomEndpoints([...customEndpoints, { ...newEndpoint }]);
      setNewEndpoint({ name: '', url: '', apiKey: '', isEnabled: true });
      setShowAddForm(false);
    }
  };

  const handleRemoveCustomEndpoint = (index) => {
    const updatedEndpoints = [...customEndpoints];
    updatedEndpoints.splice(index, 1);
    setCustomEndpoints(updatedEndpoints);
  };

  const handleTestConnection = (api) => {
    // In a real app, this would test the connection to the API
    console.log(`Testing connection to ${api}`);
    
    // Simulating a connection test
    setTimeout(() => {
      setApiEndpoints({
        ...apiEndpoints,
        [api]: {
          ...apiEndpoints[api],
          isConnected: true
        }
      });
    }, 1000);
  };

  const handleSaveConfigurations = () => {
    // In a real app, this would save the configurations
    console.log('Saving configurations:', { apiEndpoints, customEndpoints });
  };

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        API Configuration
      </Typography>
      
      <Grid container spacing={3}>
        {/* TradingView Webhook */}
        <Grid item xs={12}>
          <Card>
            <CardHeader 
              title="TradingView Webhook" 
              subheader="Configure TradingView webhook integration"
              action={
                <FormControlLabel
                  control={
                    <Switch
                      checked={apiEndpoints.tradingViewWebhook.isEnabled}
                      onChange={() => handleToggleEndpoint('tradingViewWebhook')}
                      color="primary"
                    />
                  }
                  label={apiEndpoints.tradingViewWebhook.isEnabled ? "Enabled" : "Disabled"}
                />
              }
            />
            <Divider />
            <CardContent>
              <Grid container spacing={3}>
                <Grid item xs={12} md={9}>
                  <TextField
                    fullWidth
                    label="Webhook URL"
                    value={apiEndpoints.tradingViewWebhook.url}
                    onChange={(e) => handleChangeApiValue('tradingViewWebhook', 'url', e.target.value)}
                    variant="outlined"
                    disabled={!apiEndpoints.tradingViewWebhook.isEnabled}
                    InputProps={{
                      endAdornment: (
                        <IconButton 
                          onClick={() => handleCopyToClipboard(apiEndpoints.tradingViewWebhook.url, 'webhook')}
                        >
                          {copied === 'webhook' ? <CheckIcon color="success" /> : <ContentCopyIcon />}
                        </IconButton>
                      ),
                    }}
                  />
                  <Typography variant="caption" color="textSecondary" sx={{ mt: 1, display: 'block' }}>
                    Add this URL to your TradingView alerts to trigger automated actions
                  </Typography>
                </Grid>
                <Grid item xs={12} md={3} sx={{ display: 'flex', alignItems: 'center' }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', ml: 2 }}>
                    <Chip 
                      icon={apiEndpoints.tradingViewWebhook.isConnected ? <CheckIcon /> : <CancelIcon />} 
                      label={apiEndpoints.tradingViewWebhook.isConnected ? "Connected" : "Not Connected"} 
                      color={apiEndpoints.tradingViewWebhook.isConnected ? "success" : "error"}
                      variant="outlined"
                    />
                  </Box>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>
        
        {/* Alpaca API */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardHeader 
              title="Alpaca API" 
              subheader="Configure Alpaca trading integration"
              action={
                <FormControlLabel
                  control={
                    <Switch
                      checked={apiEndpoints.alpaca.isEnabled}
                      onChange={() => handleToggleEndpoint('alpaca')}
                      color="primary"
                    />
                  }
                  label={apiEndpoints.alpaca.isEnabled ? "Enabled" : "Disabled"}
                />
              }
            />
            <Divider />
            <CardContent>
              <Box sx={{ mb: 3 }}>
                <TextField
                  fullWidth
                  label="API Key"
                  value={apiEndpoints.alpaca.apiKey}
                  onChange={(e) => handleChangeApiValue('alpaca', 'apiKey', e.target.value)}
                  variant="outlined"
                  disabled={!apiEndpoints.alpaca.isEnabled}
                  sx={{ mb: 2 }}
                />
                
                <TextField
                  fullWidth
                  label="Secret Key"
                  type={showSecretKey ? "text" : "password"}
                  value={apiEndpoints.alpaca.secretKey}
                  onChange={(e) => handleChangeApiValue('alpaca', 'secretKey', e.target.value)}
                  variant="outlined"
                  disabled={!apiEndpoints.alpaca.isEnabled}
                  InputProps={{
                    endAdornment: (
                      <Button 
                        variant="text" 
                        onClick={() => setShowSecretKey(!showSecretKey)}
                      >
                        {showSecretKey ? "Hide" : "Show"}
                      </Button>
                    ),
                  }}
                />
              </Box>
              
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Button 
                  variant="outlined" 
                  color="primary"
                  disabled={!apiEndpoints.alpaca.isEnabled}
                  onClick={() => handleTestConnection('alpaca')}
                >
                  Test Connection
                </Button>
                
                <Chip 
                  icon={apiEndpoints.alpaca.isConnected ? <CheckIcon /> : <CancelIcon />} 
                  label={apiEndpoints.alpaca.isConnected ? "Connected" : "Not Connected"} 
                  color={apiEndpoints.alpaca.isConnected ? "success" : "error"}
                  variant="outlined"
                />
              </Box>
            </CardContent>
          </Card>
        </Grid>
        
        {/* Interactive Brokers */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardHeader 
              title="Interactive Brokers" 
              subheader="Configure Interactive Brokers integration"
              action={
                <FormControlLabel
                  control={
                    <Switch
                      checked={apiEndpoints.interactiveBrokers.isEnabled}
                      onChange={() => handleToggleEndpoint('interactiveBrokers')}
                      color="primary"
                    />
                  }
                  label={apiEndpoints.interactiveBrokers.isEnabled ? "Enabled" : "Disabled"}
                />
              }
            />
            <Divider />
            <CardContent>
              <Grid container spacing={2} sx={{ mb: 3 }}>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Account ID"
                    value={apiEndpoints.interactiveBrokers.accountId}
                    onChange={(e) => handleChangeApiValue('interactiveBrokers', 'accountId', e.target.value)}
                    variant="outlined"
                    disabled={!apiEndpoints.interactiveBrokers.isEnabled}
                  />
                </Grid>
                <Grid item xs={8}>
                  <TextField
                    fullWidth
                    label="Host"
                    value={apiEndpoints.interactiveBrokers.host}
                    onChange={(e) => handleChangeApiValue('interactiveBrokers', 'host', e.target.value)}
                    variant="outlined"
                    disabled={!apiEndpoints.interactiveBrokers.isEnabled}
                  />
                </Grid>
                <Grid item xs={4}>
                  <TextField
                    fullWidth
                    label="Port"
                    value={apiEndpoints.interactiveBrokers.port}
                    onChange={(e) => handleChangeApiValue('interactiveBrokers', 'port', e.target.value)}
                    variant="outlined"
                    disabled={!apiEndpoints.interactiveBrokers.isEnabled}
                  />
                </Grid>
              </Grid>
              
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Button 
                  variant="outlined" 
                  color="primary"
                  disabled={!apiEndpoints.interactiveBrokers.isEnabled}
                  onClick={() => handleTestConnection('interactiveBrokers')}
                >
                  Test Connection
                </Button>
                
                <Chip 
                  icon={apiEndpoints.interactiveBrokers.isConnected ? <CheckIcon /> : <CancelIcon />} 
                  label={apiEndpoints.interactiveBrokers.isConnected ? "Connected" : "Not Connected"} 
                  color={apiEndpoints.interactiveBrokers.isConnected ? "success" : "error"}
                  variant="outlined"
                />
              </Box>
            </CardContent>
          </Card>
        </Grid>
        
        {/* Custom Endpoints */}
        <Grid item xs={12}>
          <Card>
            <CardHeader 
              title="Custom API Endpoints" 
              subheader="Configure additional API endpoints"
              action={
                <Button 
                  variant="outlined" 
                  color="primary"
                  startIcon={<AddIcon />}
                  onClick={() => setShowAddForm(true)}
                  size="small"
                >
                  Add Endpoint
                </Button>
              }
            />
            <Divider />
            <CardContent>
              {customEndpoints.length === 0 && !showAddForm && (
                <Typography color="textSecondary" align="center" sx={{ py: 2 }}>
                  No custom API endpoints configured
                </Typography>
              )}
              
              {customEndpoints.map((endpoint, index) => (
                <Box key={index} sx={{ mb: 3, p: 2, border: '1px solid #e0e0e0', borderRadius: 1 }}>
                  <Grid container spacing={2}>
                    <Grid item xs={11}>
                      <Typography variant="subtitle1">{endpoint.name}</Typography>
                    </Grid>
                    <Grid item xs={1} sx={{ textAlign: 'right' }}>
                      <IconButton 
                        size="small" 
                        color="error"
                        onClick={() => handleRemoveCustomEndpoint(index)}
                      >
                        <DeleteIcon />
                      </IconButton>
                    </Grid>
                    <Grid item xs={12} md={8}>
                      <TextField
                        fullWidth
                        label="URL"
                        value={endpoint.url}
                        variant="outlined"
                        size="small"
                        InputProps={{
                          readOnly: true,
                        }}
                      />
                    </Grid>
                    <Grid item xs={12} md={4}>
                      <FormControlLabel
                        control={
                          <Switch
                            checked={endpoint.isEnabled}
                            color="primary"
                            size="small"
                          />
                        }
                        label={endpoint.isEnabled ? "Enabled" : "Disabled"}
                      />
                    </Grid>
                  </Grid>
                </Box>
              ))}
              
              {showAddForm && (
                <Box sx={{ mt: 2, p: 2, border: '1px solid #e0e0e0', borderRadius: 1, bgcolor: 'background.paper' }}>
                  <Typography variant="subtitle1" gutterBottom>Add New API Endpoint</Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12}>
                      <TextField
                        fullWidth
                        label="Name"
                        value={newEndpoint.name}
                        onChange={(e) => setNewEndpoint({...newEndpoint, name: e.target.value})}
                        variant="outlined"
                        required
                      />
                    </Grid>
                    <Grid item xs={12}>
                      <TextField
                        fullWidth
                        label="URL"
                        value={newEndpoint.url}
                        onChange={(e) => setNewEndpoint({...newEndpoint, url: e.target.value})}
                        variant="outlined"
                        required
                      />
                    </Grid>
                    <Grid item xs={12}>
                      <TextField
                        fullWidth
                        label="API Key (Optional)"
                        value={newEndpoint.apiKey}
                        onChange={(e) => setNewEndpoint({...newEndpoint, apiKey: e.target.value})}
                        variant="outlined"
                      />
                    </Grid>
                    <Grid item xs={12} sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                      <Button 
                        variant="outlined" 
                        onClick={() => setShowAddForm(false)}
                      >
                        Cancel
                      </Button>
                      <Button 
                        variant="contained" 
                        color="primary"
                        onClick={handleAddCustomEndpoint}
                        disabled={!newEndpoint.name || !newEndpoint.url}
                      >
                        Add
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
              )}
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12}>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
            <Button 
              variant="contained" 
              color="primary" 
              size="large"
              startIcon={<SaveIcon />}
              onClick={handleSaveConfigurations}
            >
              Save Configurations
            </Button>
          </Box>
        </Grid>
      </Grid>
    </div>
  );
};

export default APIConfiguration; 