import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  Card, CardHeader, CardContent, CardActions,
  Grid, Typography, Button, TextField, CircularProgress,
  Divider, Chip, Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, Paper, Box, Alert, Snackbar
} from '@mui/material';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import PsychologyIcon from '@mui/icons-material/Psychology';
import BarChartIcon from '@mui/icons-material/BarChart';
import AnalyticsIcon from '@mui/icons-material/Analytics';

const AIInsights = () => {
  const [symbol, setSymbol] = useState('');
  const [symbols, setSymbols] = useState(['SPY', 'AAPL', 'MSFT', 'GOOGL']);
  const [outlookSymbols, setOutlookSymbols] = useState('SPY,QQQ,IWM,AAPL,MSFT,GOOGL,AMZN');
  const [isLoading, setIsLoading] = useState(false);
  const [marketAnalysis, setMarketAnalysis] = useState(null);
  const [marketOutlook, setMarketOutlook] = useState(null);
  const [tradeRecommendations, setTradeRecommendations] = useState([]);
  const [error, setError] = useState('');
  const [showChart, setShowChart] = useState(true);
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState('');

  const handleSymbolChange = (e) => {
    setSymbol(e.target.value.toUpperCase());
  };

  const handleOutlookSymbolsChange = (e) => {
    setOutlookSymbols(e.target.value);
  };

  const analyzeMarket = async () => {
    if (!symbol) return;
    
    setIsLoading(true);
    setError('');
    
    try {
      const response = await axios.get(`/api/ai-insights/gpt-analysis/${symbol}`, {
        params: { include_chart: showChart }
      });
      
      if (response.data.status === 'success') {
        setMarketAnalysis(response.data.analysis);
        if (response.data.analysis.trade_recommendations) {
          setTradeRecommendations(response.data.analysis.trade_recommendations);
        }
        setSnackbarMessage(`Analysis for ${symbol} completed successfully`);
        setSnackbarOpen(true);
      } else {
        setError('Failed to analyze market: ' + response.data.error);
      }
    } catch (err) {
      setError(`Error: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const getMarketOutlook = async () => {
    setIsLoading(true);
    setError('');
    
    try {
      const response = await axios.get('/api/ai-insights/market-outlook', {
        params: { symbols: outlookSymbols }
      });
      
      if (response.data.status === 'success') {
        setMarketOutlook(response.data.outlook);
        setSnackbarMessage('Market outlook analysis completed');
        setSnackbarOpen(true);
      } else {
        setError('Failed to get market outlook: ' + response.data.error);
      }
    } catch (err) {
      setError(`Error: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const analyzeMultipleMarkets = async () => {
    setIsLoading(true);
    setError('');
    
    try {
      const response = await axios.post('/api/ai-insights/multi-market-analysis', {
        symbols: symbols
      });
      
      if (response.data.status === 'success') {
        const ideas = response.data.analysis.ranked_trade_ideas || [];
        setTradeRecommendations(ideas);
        setSnackbarMessage(`Analysis completed for ${symbols.length} symbols`);
        setSnackbarOpen(true);
      } else {
        setError('Failed to analyze multiple markets: ' + response.data.error);
      }
    } catch (err) {
      setError(`Error: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const generateTradeSetups = async () => {
    setIsLoading(true);
    setError('');
    
    try {
      const response = await axios.post('/api/ai-insights/generate-trade-setups', {
        symbols: symbols
      });
      
      if (response.data.status === 'success') {
        setSnackbarMessage(`${response.data.trade_setups.length} trade setups generated`);
        setSnackbarOpen(true);
      } else {
        setError('Failed to generate trade setups: ' + response.data.error);
      }
    } catch (err) {
      setError(`Error: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddSymbol = () => {
    if (symbol && !symbols.includes(symbol)) {
      setSymbols([...symbols, symbol]);
      setSymbol('');
    }
  };

  const handleRemoveSymbol = (symbolToRemove) => {
    setSymbols(symbols.filter(s => s !== symbolToRemove));
  };

  const handleSnackbarClose = () => {
    setSnackbarOpen(false);
  };

  return (
    <div>
      <Typography variant="h4" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
        <PsychologyIcon sx={{ mr: 1 }} /> AI Market Insights
      </Typography>
      
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Card>
            <CardHeader title="GPT Market Analysis" />
            <CardContent>
              <TextField
                label="Symbol"
                variant="outlined"
                fullWidth
                value={symbol}
                onChange={handleSymbolChange}
                margin="normal"
              />
              
              <Box display="flex" alignItems="center" mt={2}>
                <Typography variant="subtitle1" sx={{ mr: 2 }}>Selected Symbols:</Typography>
                {symbols.map(s => (
                  <Chip 
                    key={s} 
                    label={s} 
                    onDelete={() => handleRemoveSymbol(s)}
                    sx={{ mr: 1 }}
                  />
                ))}
              </Box>
              
              <Box mt={2} display="flex" alignItems="center">
                <Button 
                  variant="outlined" 
                  onClick={handleAddSymbol}
                  disabled={!symbol || symbols.includes(symbol)}
                  sx={{ mr: 2 }}
                >
                  Add Symbol
                </Button>
                
                <Button 
                  variant="contained" 
                  onClick={analyzeMarket}
                  disabled={!symbol || isLoading}
                  startIcon={<AnalyticsIcon />}
                  sx={{ mr: 2 }}
                >
                  Analyze Single
                </Button>
                
                <Button 
                  variant="contained" 
                  onClick={analyzeMultipleMarkets}
                  disabled={symbols.length === 0 || isLoading}
                  startIcon={<BarChartIcon />}
                >
                  Analyze Multiple
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} md={6}>
          <Card>
            <CardHeader title="Market Outlook" />
            <CardContent>
              <TextField
                label="Symbols (comma-separated)"
                variant="outlined"
                fullWidth
                value={outlookSymbols}
                onChange={handleOutlookSymbolsChange}
                margin="normal"
              />
              
              <Box mt={2} display="flex" justifyContent="space-between">
                <Button 
                  variant="contained" 
                  onClick={getMarketOutlook}
                  disabled={isLoading}
                  startIcon={<PsychologyIcon />}
                >
                  Get Market Outlook
                </Button>
                
                <Button 
                  variant="contained" 
                  color="secondary"
                  onClick={generateTradeSetups}
                  disabled={symbols.length === 0 || isLoading}
                >
                  Generate Trade Setups
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        
        {isLoading && (
          <Grid item xs={12}>
            <Box display="flex" justifyContent="center" mt={4}>
              <CircularProgress />
            </Box>
          </Grid>
        )}
        
        {error && (
          <Grid item xs={12}>
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          </Grid>
        )}
        
        {marketAnalysis && (
          <Grid item xs={12}>
            <Card>
              <CardHeader 
                title={`Market Analysis: ${marketAnalysis.symbol}`} 
                subheader={`Current Price: $${marketAnalysis.current_price.toFixed(2)}`}
              />
              <CardContent>
                <Typography variant="body1" sx={{ whiteSpace: 'pre-line' }}>
                  {marketAnalysis.market_analysis}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        )}
        
        {marketOutlook && (
          <Grid item xs={12}>
            <Card>
              <CardHeader title="Market Outlook" />
              <CardContent>
                <Typography variant="body1" sx={{ whiteSpace: 'pre-line' }}>
                  {marketOutlook.market_outlook}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        )}
        
        {tradeRecommendations.length > 0 && (
          <Grid item xs={12}>
            <Card>
              <CardHeader title="Trade Recommendations" />
              <CardContent>
                <TableContainer component={Paper}>
                  <Table>
                    <TableHead>
                      <TableRow>
                        <TableCell>Symbol</TableCell>
                        <TableCell>Direction</TableCell>
                        <TableCell>Entry Price</TableCell>
                        <TableCell>Stop Loss</TableCell>
                        <TableCell>Target</TableCell>
                        <TableCell>Risk/Reward</TableCell>
                        <TableCell>Confidence</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {tradeRecommendations.map((rec, index) => (
                        <TableRow key={index}>
                          <TableCell>{rec.symbol}</TableCell>
                          <TableCell>
                            {rec.direction === 'LONG' ? (
                              <Chip 
                                icon={<TrendingUpIcon />} 
                                label="LONG" 
                                color="success" 
                                size="small" 
                              />
                            ) : (
                              <Chip 
                                icon={<TrendingDownIcon />} 
                                label="SHORT" 
                                color="error" 
                                size="small" 
                              />
                            )}
                          </TableCell>
                          <TableCell>${rec.entry_price?.toFixed(2) || 'N/A'}</TableCell>
                          <TableCell>${rec.stop_loss?.toFixed(2) || 'N/A'}</TableCell>
                          <TableCell>${rec.target_price?.toFixed(2) || 'N/A'}</TableCell>
                          <TableCell>{rec.risk_reward?.toFixed(2) || 'N/A'}</TableCell>
                          <TableCell>
                            <Chip 
                              label={rec.confidence} 
                              color={
                                rec.confidence === 'HIGH' ? 'success' : 
                                rec.confidence === 'MEDIUM' ? 'primary' : 'warning'
                              }
                              size="small"
                            />
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>
        )}
      </Grid>
      
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={6000}
        onClose={handleSnackbarClose}
        message={snackbarMessage}
      />
    </div>
  );
};

export default AIInsights; 