import React, { useState, useEffect, useRef } from 'react';
import { 
  Box, 
  Typography, 
  Button, 
  TextField,
  Paper,
  alpha,
  useTheme 
} from '@mui/material';
import { motion, AnimatePresence } from 'framer-motion';
import { Lock, Fingerprint } from '@mui/icons-material';

// Fixed PIN
const CORRECT_PIN = '8080';

// Define paths to audio files with PUBLIC_URL to ensure they work in all environments
const GRANTED_SOUND_PATH = `${process.env.PUBLIC_URL}/sounds/access-granted-87075.mp3`;
const DENIED_SOUND_PATH = `${process.env.PUBLIC_URL}/sounds/access-denied-101308.mp3`;

// Backup paths in case the main paths fail
const BACKUP_PATHS = {
  granted: [
    `${process.env.PUBLIC_URL}/sounds/access-granted.mp3`,
    'sounds/access-granted.mp3',
    'sounds/access-granted-87075.mp3',
    '/sounds/access-granted.mp3',
    '/sounds/access-granted-87075.mp3'
  ],
  denied: [
    `${process.env.PUBLIC_URL}/sounds/access-denied.mp3`,
    'sounds/access-denied.mp3',
    'sounds/access-denied-101308.mp3',
    '/sounds/access-denied.mp3',
    '/sounds/access-denied-101308.mp3'
  ]
};

const VaultAuth = ({ onAuthenticated }) => {
  const theme = useTheme();
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);
  const [success, setSuccess] = useState(false);
  const [showMessage, setShowMessage] = useState(false);
  const [message, setMessage] = useState('');
  const accessGrantedRef = useRef(null);
  const accessDeniedRef = useRef(null);
  const [audioLoaded, setAudioLoaded] = useState({
    granted: false,
    denied: false
  });

  // This function attempts to play a sound
  const playSound = (soundType) => {
    let audioElement = null;
    
    if (soundType === 'granted') {
      audioElement = accessGrantedRef.current;
    } else if (soundType === 'denied') {
      audioElement = accessDeniedRef.current;
    }
    
    if (!audioElement) {
      console.error(`Audio element for ${soundType} is not available`);
      // Create a silent audio element as fallback
      audioElement = new Audio();
      if (soundType === 'granted') {
        accessGrantedRef.current = audioElement;
      } else {
        accessDeniedRef.current = audioElement;
      }
      return;
    }
    
    // Reset the audio to the beginning if it was already played
    audioElement.currentTime = 0;
    
    // Set volume to make sure it's audible
    audioElement.volume = 1.0;
    
    // Try to play the sound with better error handling
    try {
      const playPromise = audioElement.play();
      
      // Modern browsers return a promise from the play function
      if (playPromise !== undefined) {
        playPromise.catch(error => {
          console.error(`Error playing ${soundType} sound:`, error);
          
          // If there was a user interaction, try playing again
          document.addEventListener('click', function playOnClick() {
            audioElement.play().catch(e => console.error('Retry error:', e));
            document.removeEventListener('click', playOnClick);
          }, { once: true });
        });
      }
    } catch (error) {
      console.error(`Exception playing ${soundType} sound:`, error);
    }
  };

  // Load audio files
  useEffect(() => {
    const loadSound = (type, mainPath, backupPaths) => {
      console.log(`Attempting to load ${type} sound from ${mainPath}`);
      
      const audio = new Audio(mainPath);
      
      audio.addEventListener('canplaythrough', () => {
        console.log(`${type} sound loaded successfully from ${mainPath}`);
        if (type === 'granted') {
          accessGrantedRef.current = audio;
        } else {
          accessDeniedRef.current = audio;
        }
        setAudioLoaded(prev => ({ ...prev, [type]: true }));
      });
      
      audio.addEventListener('error', () => {
        console.error(`Error loading ${type} sound from ${mainPath}, trying backup paths`);
        tryBackupPaths(type, backupPaths);
      });
      
      audio.load();
    };
    
    const tryBackupPaths = (type, paths) => {
      if (paths.length === 0) {
        console.error(`Failed to load ${type} sound after trying all paths`);
        // Create a silent Audio element as a fallback
        const silentAudio = new Audio();
        if (type === 'granted') {
          accessGrantedRef.current = silentAudio;
        } else {
          accessDeniedRef.current = silentAudio;
        }
        setAudioLoaded(prev => ({ ...prev, [type]: true }));
        return;
      }
      
      const path = paths[0];
      console.log(`Trying backup path for ${type} sound: ${path}`);
      
      const audio = new Audio(path);
      
      audio.addEventListener('canplaythrough', () => {
        console.log(`${type} sound loaded successfully from backup path: ${path}`);
        if (type === 'granted') {
          accessGrantedRef.current = audio;
        } else {
          accessDeniedRef.current = audio;
        }
        setAudioLoaded(prev => ({ ...prev, [type]: true }));
      });
      
      audio.addEventListener('error', () => {
        console.log(`Failed to load ${type} sound from backup path: ${path}`);
        tryBackupPaths(type, paths.slice(1));
      });
      
      audio.load();
    };
    
    // Start loading sounds
    loadSound('granted', GRANTED_SOUND_PATH, BACKUP_PATHS.granted);
    loadSound('denied', DENIED_SOUND_PATH, BACKUP_PATHS.denied);
    
    // Cleanup function
    return () => {
      if (accessGrantedRef.current) {
        accessGrantedRef.current.pause();
        accessGrantedRef.current = null;
      }
      
      if (accessDeniedRef.current) {
        accessDeniedRef.current.pause();
        accessDeniedRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    // Auto-validate when 4 digits are entered
    if (pin.length === 4) {
      validatePin();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pin]);

  const handlePinChange = (e) => {
    const value = e.target.value;
    // Only allow numbers and max 4 digits
    if (/^\d{0,4}$/.test(value)) {
      setPin(value);
      setError(false);
    }
  };

  const handleKeypadClick = (digit) => {
    if (pin.length < 4) {
      setPin(prev => prev + digit);
    }
  };

  const handleClear = () => {
    setPin('');
    setError(false);
  };

  const validatePin = () => {
    setShowMessage(true);
    
    if (pin === CORRECT_PIN) {
      setSuccess(true);
      setMessage('ACCESS GRANTED');
      
      // Play the access granted sound
      playSound('granted');
      
      // Wait for animation to complete before redirecting
      setTimeout(() => {
        onAuthenticated();
      }, 2000);
    } else {
      setError(true);
      setMessage('ACCESS DENIED');
      
      // Play the access denied sound
      playSound('denied');
      
      // Clear the error message after 2 seconds
      setTimeout(() => {
        setShowMessage(false);
        setPin('');
      }, 2000);
    }
  };

  // Create the keypad buttons
  const renderKeypad = () => {
    const keypad = [];
    for (let i = 1; i <= 9; i++) {
      keypad.push(
        <Button 
          key={i}
          onClick={() => handleKeypadClick(i)}
          variant="outlined"
          sx={{
            width: 64,
            height: 64,
            borderRadius: '8px',
            margin: '6px',
            backgroundColor: alpha(theme.palette.primary.main, 0.1),
            color: theme.palette.primary.main,
            fontFamily: 'Share Tech Mono, monospace',
            fontSize: '1.5rem',
            border: `1px solid ${alpha(theme.palette.primary.main, 0.3)}`,
            '&:hover': {
              backgroundColor: alpha(theme.palette.primary.main, 0.2),
              border: `1px solid ${theme.palette.primary.main}`,
            }
          }}
        >
          {i}
        </Button>
      );
    }
    
    // Add 0 button
    keypad.push(
      <Button 
        key={0}
        onClick={() => handleKeypadClick(0)}
        variant="outlined"
        sx={{
          width: 64,
          height: 64,
          borderRadius: '8px',
          margin: '6px',
          backgroundColor: alpha(theme.palette.primary.main, 0.1),
          color: theme.palette.primary.main,
          fontFamily: 'Share Tech Mono, monospace',
          fontSize: '1.5rem',
          border: `1px solid ${alpha(theme.palette.primary.main, 0.3)}`,
          '&:hover': {
            backgroundColor: alpha(theme.palette.primary.main, 0.2),
            border: `1px solid ${theme.palette.primary.main}`,
          }
        }}
      >
        0
      </Button>
    );
    
    return (
      <Box sx={{ 
        display: 'flex', 
        flexWrap: 'wrap', 
        justifyContent: 'center',
        width: 230
      }}>
        {keypad}
      </Box>
    );
  };

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: alpha(theme.palette.background.default, 0.85),
          backdropFilter: 'blur(8px)',
          zIndex: 1300,
        }}
      >
        <motion.div
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ type: 'spring', damping: 20, stiffness: 100 }}
        >
          <Paper
            elevation={24}
            sx={{
              padding: 4,
              borderRadius: 4,
              maxWidth: 400,
              width: '100%',
              backgroundColor: alpha(theme.palette.background.paper, 0.9),
              border: `1px solid ${alpha(theme.palette.primary.main, 0.3)}`,
              position: 'relative',
              overflow: 'hidden',
            }}
          >
            {/* Animated glowing background */}
            <Box
              sx={{
                position: 'absolute',
                top: '-50%',
                left: '-50%',
                right: '-50%',
                bottom: '-50%',
                background: `radial-gradient(circle, ${alpha(theme.palette.primary.main, 0.1)} 0%, transparent 70%)`,
                animation: 'pulse 3s infinite ease-in-out',
                '@keyframes pulse': {
                  '0%': { opacity: 0.3, transform: 'scale(0.9)' },
                  '50%': { opacity: 0.6, transform: 'scale(1.1)' },
                  '100%': { opacity: 0.3, transform: 'scale(0.9)' },
                },
              }}
            />
            
            <Box sx={{ position: 'relative', zIndex: 1 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', mb: 3 }}>
                <motion.div
                  animate={{ rotate: [0, 360] }}
                  transition={{ duration: 3, repeat: Infinity, ease: 'linear' }}
                >
                  <Lock 
                    sx={{ 
                      fontSize: 48, 
                      color: error ? theme.palette.error.main : 
                             success ? theme.palette.success.main : 
                             theme.palette.primary.main,
                      mr: 2 
                    }} 
                  />
                </motion.div>
                <Typography 
                  variant="h4" 
                  component="h1" 
                  fontFamily="Share Tech Mono, monospace"
                  color={theme.palette.primary.main}
                  sx={{ textShadow: `0 0 8px ${alpha(theme.palette.primary.main, 0.5)}` }}
                >
                  VAULT ACCESS
                </Typography>
              </Box>
              
              <Typography 
                align="center" 
                variant="subtitle1" 
                mb={3}
                fontFamily="Share Tech Mono, monospace"
                color={theme.palette.text.secondary}
                sx={{ 
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 1
                }}
              >
                <Fingerprint color="primary" />
                Enter 4-Digit Security PIN
              </Typography>
              
              {/* PIN Display */}
              <Box sx={{ mb: 3, position: 'relative' }}>
                <TextField
                  fullWidth
                  variant="outlined"
                  type="password"
                  value={pin}
                  onChange={handlePinChange}
                  inputProps={{ 
                    maxLength: 4,
                    style: { 
                      textAlign: 'center',
                      fontFamily: 'Share Tech Mono, monospace',
                      fontSize: '2rem',
                      letterSpacing: '1rem',
                      color: error ? theme.palette.error.main : 
                             success ? theme.palette.success.main : 
                             theme.palette.primary.main
                    } 
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      '& fieldset': {
                        borderColor: error ? theme.palette.error.main : 
                                    success ? theme.palette.success.main : 
                                    alpha(theme.palette.primary.main, 0.5),
                        borderWidth: 2,
                        borderRadius: 2
                      },
                      '&:hover fieldset': {
                        borderColor: error ? theme.palette.error.main : 
                                    success ? theme.palette.success.main : 
                                    theme.palette.primary.main
                      },
                      '&.Mui-focused fieldset': {
                        borderColor: error ? theme.palette.error.main : 
                                    success ? theme.palette.success.main : 
                                    theme.palette.primary.main
                      }
                    }
                  }}
                />
                
                {/* Digital display showing PIN as dots */}
                <Box 
                  sx={{ 
                    position: 'absolute', 
                    top: '50%', 
                    left: 0, 
                    right: 0, 
                    transform: 'translateY(-50%)',
                    display: 'flex',
                    justifyContent: 'center',
                    gap: 2,
                    pointerEvents: 'none'
                  }}
                >
                  {[...Array(4)].map((_, index) => (
                    <Box 
                      key={index}
                      sx={{
                        width: 20,
                        height: 20,
                        borderRadius: '50%',
                        backgroundColor: pin.length > index 
                          ? error 
                            ? theme.palette.error.main 
                            : success 
                              ? theme.palette.success.main 
                              : theme.palette.primary.main
                          : 'transparent',
                        border: `2px solid ${
                          error 
                            ? alpha(theme.palette.error.main, 0.5) 
                            : success 
                              ? alpha(theme.palette.success.main, 0.5) 
                              : alpha(theme.palette.primary.main, 0.5)
                        }`,
                        transition: 'all 0.2s ease'
                      }}
                    />
                  ))}
                </Box>
              </Box>

              {/* Auth message */}
              <AnimatePresence>
                {showMessage && (
                  <motion.div
                    initial={{ opacity: 0, y: -20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 20 }}
                  >
                    <Typography 
                      align="center" 
                      variant="h6" 
                      fontFamily="Share Tech Mono, monospace"
                      mb={3}
                      color={error ? theme.palette.error.main : theme.palette.success.main}
                      sx={{ 
                        fontWeight: 'bold',
                        textShadow: `0 0 10px ${error ? alpha(theme.palette.error.main, 0.5) : alpha(theme.palette.success.main, 0.5)}`,
                        animation: error || success ? 'pulse 1s infinite' : 'none',
                        '@keyframes pulse': {
                          '0%': { opacity: 0.7 },
                          '50%': { opacity: 1 },
                          '100%': { opacity: 0.7 },
                        }
                      }}
                    >
                      {message}
                    </Typography>
                  </motion.div>
                )}
              </AnimatePresence>
              
              {/* Sound loading status */}
              {!audioLoaded.granted && !audioLoaded.denied && (
                <Typography 
                  align="center" 
                  variant="caption" 
                  color="text.secondary"
                  sx={{ display: 'block', mb: 2 }}
                >
                  Loading sound effects...
                </Typography>
              )}
              
              {/* Keypad */}
              <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                {renderKeypad()}
                
                <Box sx={{ display: 'flex', gap: 2, mt: 2 }}>
                  <Button 
                    variant="outlined" 
                    color="error" 
                    onClick={handleClear}
                    sx={{ 
                      width: 140,
                      fontFamily: 'Share Tech Mono, monospace',
                      borderRadius: 2
                    }}
                  >
                    CLEAR
                  </Button>
                </Box>
              </Box>
            </Box>
          </Paper>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

export default VaultAuth; 