import React from 'react';
import { 
  Typography, 
  Grid, 
  Card, 
  CardContent, 
  CardHeader,
  Button,
  List,
  ListItem,
  ListItemText,
  Divider,
  Box
} from '@mui/material';

const Strategies = () => {
  const strategyList = [
    {
      name: 'Trend Following',
      description: 'Based on moving average crossovers and trend indicators',
      status: 'Active'
    },
    {
      name: 'Mean Reversion',
      description: 'Trades based on oversold/overbought conditions',
      status: 'Active'
    },
    {
      name: 'Breakout',
      description: 'Detects and trades breakouts from consolidation patterns',
      status: 'Inactive'
    },
    {
      name: 'Momentum',
      description: 'Utilizes momentum indicators to find strong directional moves',
      status: 'Active'
    }
  ];

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Trading Strategies
      </Typography>
      
      <Grid container spacing={3}>
        <Grid item xs={12} md={8}>
          <Card>
            <CardHeader title="Available Strategies" />
            <CardContent>
              <List>
                {strategyList.map((strategy, index) => (
                  <React.Fragment key={index}>
                    <ListItem>
                      <Grid container spacing={2}>
                        <Grid item xs={4}>
                          <ListItemText 
                            primary={strategy.name} 
                            secondary={`Status: ${strategy.status}`}
                          />
                        </Grid>
                        <Grid item xs={6}>
                          <ListItemText primary={strategy.description} />
                        </Grid>
                        <Grid item xs={2}>
                          <Box display="flex" justifyContent="flex-end">
                            <Button 
                              variant="outlined" 
                              color={strategy.status === 'Active' ? 'error' : 'primary'}
                              size="small"
                            >
                              {strategy.status === 'Active' ? 'Disable' : 'Enable'}
                            </Button>
                          </Box>
                        </Grid>
                      </Grid>
                    </ListItem>
                    {index < strategyList.length - 1 && <Divider />}
                  </React.Fragment>
                ))}
              </List>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} md={4}>
          <Card>
            <CardHeader title="Strategy Configuration" />
            <CardContent>
              <Typography variant="body2" color="textSecondary">
                Select a strategy to configure its parameters.
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </div>
  );
};

export default Strategies; 