import React, { useEffect, useState, useRef } from 'react';
import { Box, Typography, CircularProgress, useTheme, Card, CardContent, CardHeader, Grid, TextField, MenuItem } from '@mui/material';
import { ResponsiveLine } from '@nivo/line';
import { alpha } from '@mui/material/styles';
import axios from 'axios';

const TradingChart = ({ symbol = 'SPY', interval = '1d', duration = '3mo' }) => {
  const theme = useTheme();
  const [loading, setLoading] = useState(true);
  const [chartData, setChartData] = useState([]);
  const [error, setError] = useState(null);
  const [selectedSymbol, setSelectedSymbol] = useState(symbol);
  const [selectedInterval, setSelectedInterval] = useState(interval);
  // Use ref to prevent unnecessary re-renders that might cause the chart to revert
  const dataFetchedRef = useRef(false);

  const intervals = [
    { value: '1d', label: 'Daily' },
    { value: '1h', label: 'Hourly' },
    { value: '15m', label: 'Every 15 min' }
  ];

  useEffect(() => {
    // Only fetch data if we haven't already or if the dependencies changed
    if (!dataFetchedRef.current || 
        (dataFetchedRef.current && 
         (dataFetchedRef.current.symbol !== selectedSymbol || 
          dataFetchedRef.current.interval !== selectedInterval || 
          dataFetchedRef.current.duration !== duration))) {
      
      setLoading(true);
      setError(null);
      
      const fetchData = async () => {
        try {
          // In a real application, this would fetch actual market data
          // This is a mock function that generates sample price data
          const generateMockPriceData = () => {
            const mockData = [];
            const now = new Date();
            let price = 100 + Math.random() * 50; // Starting price between 100-150
            
            // Determine number of data points based on interval
            let dataPoints = 30;
            if (selectedInterval === '1h') dataPoints = 24 * 7;
            if (selectedInterval === '15m') dataPoints = 4 * 24 * 3;
            
            for (let i = 0; i < dataPoints; i++) {
              // Create date based on interval
              const date = new Date(now);
              if (selectedInterval === '1d') {
                date.setDate(date.getDate() - (dataPoints - i));
              } else if (selectedInterval === '1h') {
                date.setHours(date.getHours() - (dataPoints - i));
              } else {
                date.setMinutes(date.getMinutes() - ((dataPoints - i) * 15));
              }
              
              // Simulate price movement
              const change = (Math.random() - 0.48) * 2; // Slight upward bias
              price += change;
              if (price < 50) price = 50; // Ensure price doesn't go too low
              
              mockData.push({
                x: date.toISOString(),
                y: parseFloat(price.toFixed(2))
              });
            }

            setTimeout(() => {
              setChartData([{
                id: selectedSymbol,
                data: mockData
              }]);
              // Mark as fetched to prevent re-rendering issues
              dataFetchedRef.current = {
                symbol: selectedSymbol,
                interval: selectedInterval,
                duration: duration
              };
              setLoading(false);
            }, 500);
          };
          
          generateMockPriceData();
        } catch (error) {
          console.error('Error fetching chart data:', error);
          setError('Failed to fetch chart data');
          setLoading(false);
        }
      };

      fetchData();
    }
  }, [selectedSymbol, selectedInterval, duration, theme]);

  const handleSymbolChange = (event) => {
    setSelectedSymbol(event.target.value);
  };

  const handleIntervalChange = (event) => {
    setSelectedInterval(event.target.value);
  };

  // Validate chart data to prevent SVG path errors
  const validateChartData = (data) => {
    if (!data || !Array.isArray(data) || data.length === 0) {
      // Return default valid data if no data is provided
      return [
        {
          id: selectedSymbol || 'default',
          color: theme.palette.primary.main,
          data: [
            { x: "Day 1", y: 100 },
            { x: "Day 2", y: 101 }
          ]
        }
      ];
    }
    
    // Check each series
    return data.map(series => {
      // Ensure series has an id and data array
      if (!series.id || !series.data || !Array.isArray(series.data)) {
        return {
          id: series.id || 'default',
          color: series.color || theme.palette.primary.main,
          data: [
            { x: "Day 1", y: 100 },
            { x: "Day 2", y: 101 }
          ]
        };
      }
      
      // If data array is empty, add default points
      if (series.data.length === 0) {
        series.data = [
          { x: "Day 1", y: 100 },
          { x: "Day 2", y: 101 }
        ];
      }
      
      // Ensure each data point has valid x and y values
      series.data = series.data.map(point => ({
        x: point.x || "Unknown",
        y: typeof point.y === 'number' ? point.y : 100
      }));
      
      return series;
    });
  };

  if (loading) {
    return (
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'center', 
        alignItems: 'center', 
        height: '100%' 
      }}>
        <CircularProgress size={40} sx={{ color: theme.palette.primary.main }} />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'center', 
        alignItems: 'center', 
        height: '100%' 
      }}>
        <Typography color="error">{error}</Typography>
      </Box>
    );
  }

  // Validate chart data before rendering
  const validatedChartData = validateChartData(chartData);

  return (
    <Card>
      <CardHeader title="Price Chart" />
      <CardContent>
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Symbol"
              value={selectedSymbol}
              onChange={handleSymbolChange}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              select
              fullWidth
              label="Interval"
              value={selectedInterval}
              onChange={handleIntervalChange}
              variant="outlined"
            >
              {intervals.map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </TextField>
          </Grid>
        </Grid>

        <Box sx={{ height: 400 }}>
          {loading ? (
            <Box
              sx={{
                height: '100%',
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center'
              }}
            >
              Loading chart data...
            </Box>
          ) : (
            <ResponsiveLine
              data={validatedChartData}
              margin={{ top: 20, right: 20, bottom: 60, left: 80 }}
              xScale={{
                type: 'time',
                format: '%Y-%m-%dT%H:%M:%S.%LZ',
                precision: 'minute',
              }}
              yScale={{
                type: 'linear',
                min: 'auto',
                max: 'auto',
              }}
              xFormat="time:%Y-%m-%d %H:%M"
              yFormat=" >-.2f"
              axisBottom={{
                format: '%b %d',
                tickRotation: -45,
                legend: 'Date',
                legendOffset: 40,
                legendPosition: 'middle'
              }}
              axisLeft={{
                legend: 'Price',
                legendOffset: -60,
                legendPosition: 'middle'
              }}
              colors={{ scheme: 'set2' }}
              pointSize={0}
              pointBorderWidth={1}
              pointBorderColor={{ from: 'serieColor' }}
              enableArea={true}
              areaOpacity={0.1}
              useMesh={true}
              enableGridX={false}
              curve="monotoneX"
              crosshairType="cross"
              tooltip={({ point }) => {
                return (
                  <div
                    style={{
                      background: 'white',
                      padding: '9px 12px',
                      border: '1px solid #ccc',
                      color: '#333',
                      boxShadow: '0 1px 3px rgba(0,0,0,0.12)'
                    }}
                  >
                    <div><strong>{point.serieId}</strong></div>
                    <div>Date: {new Date(point.data.x).toLocaleString()}</div>
                    <div>Price: ${point.data.y}</div>
                  </div>
                );
              }}
            />
          )}
        </Box>
      </CardContent>
    </Card>
  );
};

export default TradingChart;