import React, { useState } from 'react';
import { 
  Typography, 
  Grid, 
  Card, 
  CardContent, 
  CardHeader,
  TextField,
  Button,
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Divider,
  Chip,
  Switch,
  FormControlLabel,
  Alert
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CodeIcon from '@mui/icons-material/Code';
import SaveIcon from '@mui/icons-material/Save';
import CancelIcon from '@mui/icons-material/Cancel';

const TradingViewAlerts = () => {
  const [alerts, setAlerts] = useState([
    { 
      id: 1, 
      name: 'SPY Breakout Alert', 
      symbol: 'SPY', 
      condition: 'price crosses above $430', 
      action: 'BUY', 
      quantity: 100,
      isActive: true 
    },
    { 
      id: 2, 
      name: 'AAPL Moving Average Crossover', 
      symbol: 'AAPL', 
      condition: 'MA(20) crosses above MA(50)', 
      action: 'BUY', 
      quantity: 50,
      isActive: true 
    },
    { 
      id: 3, 
      name: 'TSLA Support Break', 
      symbol: 'TSLA', 
      condition: 'price crosses below $180', 
      action: 'SELL', 
      quantity: 25,
      isActive: false 
    }
  ]);
  
  const [editingAlert, setEditingAlert] = useState(null);
  const [newAlert, setNewAlert] = useState({
    name: '',
    symbol: '',
    condition: '',
    action: 'BUY',
    quantity: 0,
    isActive: true
  });
  const [showNewAlertForm, setShowNewAlertForm] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState('https://your-server.com/webhook/tradingview');
  const [copied, setCopied] = useState(false);

  const handleToggleAlert = (id) => {
    setAlerts(alerts.map(alert => 
      alert.id === id ? { ...alert, isActive: !alert.isActive } : alert
    ));
  };

  const handleEditAlert = (alert) => {
    setEditingAlert({ ...alert });
  };

  const handleSaveEdit = () => {
    setAlerts(alerts.map(alert => 
      alert.id === editingAlert.id ? editingAlert : alert
    ));
    setEditingAlert(null);
  };

  const handleCancelEdit = () => {
    setEditingAlert(null);
  };

  const handleDeleteAlert = (id) => {
    setAlerts(alerts.filter(alert => alert.id !== id));
  };

  const handleAddAlert = () => {
    const newId = Math.max(0, ...alerts.map(a => a.id)) + 1;
    setAlerts([...alerts, { ...newAlert, id: newId }]);
    setNewAlert({
      name: '',
      symbol: '',
      condition: '',
      action: 'BUY',
      quantity: 0,
      isActive: true
    });
    setShowNewAlertForm(false);
  };

  const handleCopyWebhook = () => {
    navigator.clipboard.writeText(webhookUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        TradingView Alerts
      </Typography>
      
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Alert severity="info" sx={{ mb: 3 }}>
            TradingView alerts let you create automated trading signals based on technical conditions.
            Configure your alerts below and use the webhook URL in TradingView to trigger them.
          </Alert>
        </Grid>
        
        <Grid item xs={12}>
          <Card>
            <CardHeader title="Webhook Configuration" />
            <Divider />
            <CardContent>
              <Grid container spacing={2} alignItems="center">
                <Grid item xs={12} md={8}>
                  <TextField
                    fullWidth
                    label="Webhook URL"
                    value={webhookUrl}
                    onChange={(e) => setWebhookUrl(e.target.value)}
                    variant="outlined"
                    InputProps={{
                      readOnly: true,
                      endAdornment: (
                        <IconButton onClick={handleCopyWebhook}>
                          <ContentCopyIcon />
                        </IconButton>
                      ),
                    }}
                  />
                  {copied && (
                    <Typography variant="caption" color="success.main" sx={{ mt: 1, display: 'block' }}>
                      Copied to clipboard!
                    </Typography>
                  )}
                </Grid>
                <Grid item xs={12} md={4}>
                  <Button 
                    variant="outlined" 
                    color="primary"
                    startIcon={<CodeIcon />}
                    fullWidth
                  >
                    View JSON Format
                  </Button>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12}>
          <Card>
            <CardHeader 
              title="Alert Configuration" 
              action={
                <Button 
                  variant="contained" 
                  color="primary"
                  startIcon={<AddIcon />}
                  onClick={() => setShowNewAlertForm(true)}
                  disabled={showNewAlertForm}
                >
                  New Alert
                </Button>
              }
            />
            <Divider />
            <CardContent>
              {showNewAlertForm && (
                <Paper elevation={0} sx={{ p: 2, mb: 3, border: '1px solid #e0e0e0' }}>
                  <Typography variant="h6" gutterBottom>Create New Alert</Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Alert Name"
                        value={newAlert.name}
                        onChange={(e) => setNewAlert({...newAlert, name: e.target.value})}
                        required
                      />
                    </Grid>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Symbol"
                        value={newAlert.symbol}
                        onChange={(e) => setNewAlert({...newAlert, symbol: e.target.value})}
                        required
                      />
                    </Grid>
                    <Grid item xs={12}>
                      <TextField
                        fullWidth
                        label="Condition"
                        value={newAlert.condition}
                        onChange={(e) => setNewAlert({...newAlert, condition: e.target.value})}
                        placeholder="e.g. price crosses above $430"
                        required
                      />
                    </Grid>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        select
                        label="Action"
                        value={newAlert.action}
                        onChange={(e) => setNewAlert({...newAlert, action: e.target.value})}
                        SelectProps={{
                          native: true,
                        }}
                      >
                        <option value="BUY">BUY</option>
                        <option value="SELL">SELL</option>
                      </TextField>
                    </Grid>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        type="number"
                        label="Quantity"
                        value={newAlert.quantity}
                        onChange={(e) => setNewAlert({...newAlert, quantity: parseInt(e.target.value) || 0})}
                        required
                      />
                    </Grid>
                    <Grid item xs={12}>
                      <FormControlLabel
                        control={
                          <Switch
                            checked={newAlert.isActive}
                            onChange={(e) => setNewAlert({...newAlert, isActive: e.target.checked})}
                            color="primary"
                          />
                        }
                        label="Active"
                      />
                    </Grid>
                    <Grid item xs={12} sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                      <Button 
                        variant="outlined" 
                        onClick={() => setShowNewAlertForm(false)}
                      >
                        Cancel
                      </Button>
                      <Button 
                        variant="contained" 
                        color="primary"
                        onClick={handleAddAlert}
                        disabled={!newAlert.name || !newAlert.symbol || !newAlert.condition}
                      >
                        Add Alert
                      </Button>
                    </Grid>
                  </Grid>
                </Paper>
              )}
              
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>Name</TableCell>
                      <TableCell>Symbol</TableCell>
                      <TableCell>Condition</TableCell>
                      <TableCell>Action</TableCell>
                      <TableCell>Quantity</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell align="center">Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {alerts.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={7} align="center">
                          <Typography color="textSecondary">No alerts configured</Typography>
                        </TableCell>
                      </TableRow>
                    ) : (
                      alerts.map((alert) => (
                        <TableRow key={alert.id}>
                          {editingAlert && editingAlert.id === alert.id ? (
                            // Edit mode
                            <>
                              <TableCell>
                                <TextField
                                  fullWidth
                                  size="small"
                                  value={editingAlert.name}
                                  onChange={(e) => setEditingAlert({...editingAlert, name: e.target.value})}
                                />
                              </TableCell>
                              <TableCell>
                                <TextField
                                  fullWidth
                                  size="small"
                                  value={editingAlert.symbol}
                                  onChange={(e) => setEditingAlert({...editingAlert, symbol: e.target.value})}
                                />
                              </TableCell>
                              <TableCell>
                                <TextField
                                  fullWidth
                                  size="small"
                                  value={editingAlert.condition}
                                  onChange={(e) => setEditingAlert({...editingAlert, condition: e.target.value})}
                                />
                              </TableCell>
                              <TableCell>
                                <TextField
                                  fullWidth
                                  size="small"
                                  select
                                  value={editingAlert.action}
                                  onChange={(e) => setEditingAlert({...editingAlert, action: e.target.value})}
                                  SelectProps={{
                                    native: true,
                                  }}
                                >
                                  <option value="BUY">BUY</option>
                                  <option value="SELL">SELL</option>
                                </TextField>
                              </TableCell>
                              <TableCell>
                                <TextField
                                  fullWidth
                                  size="small"
                                  type="number"
                                  value={editingAlert.quantity}
                                  onChange={(e) => setEditingAlert({...editingAlert, quantity: parseInt(e.target.value) || 0})}
                                />
                              </TableCell>
                              <TableCell>
                                <FormControlLabel
                                  control={
                                    <Switch
                                      size="small"
                                      checked={editingAlert.isActive}
                                      onChange={(e) => setEditingAlert({...editingAlert, isActive: e.target.checked})}
                                      color="primary"
                                    />
                                  }
                                  label={editingAlert.isActive ? "Active" : "Inactive"}
                                />
                              </TableCell>
                              <TableCell align="center">
                                <Box sx={{ display: 'flex', justifyContent: 'center', gap: 1 }}>
                                  <IconButton size="small" color="primary" onClick={handleSaveEdit}>
                                    <SaveIcon fontSize="small" />
                                  </IconButton>
                                  <IconButton size="small" color="default" onClick={handleCancelEdit}>
                                    <CancelIcon fontSize="small" />
                                  </IconButton>
                                </Box>
                              </TableCell>
                            </>
                          ) : (
                            // View mode
                            <>
                              <TableCell>{alert.name}</TableCell>
                              <TableCell>{alert.symbol}</TableCell>
                              <TableCell>{alert.condition}</TableCell>
                              <TableCell>
                                <Chip 
                                  label={alert.action} 
                                  color={alert.action === 'BUY' ? 'success' : 'error'} 
                                  size="small" 
                                  variant="outlined"
                                />
                              </TableCell>
                              <TableCell>{alert.quantity}</TableCell>
                              <TableCell>
                                <FormControlLabel
                                  control={
                                    <Switch
                                      size="small"
                                      checked={alert.isActive}
                                      onChange={() => handleToggleAlert(alert.id)}
                                      color="primary"
                                    />
                                  }
                                  label={alert.isActive ? "Active" : "Inactive"}
                                />
                              </TableCell>
                              <TableCell align="center">
                                <Box sx={{ display: 'flex', justifyContent: 'center', gap: 1 }}>
                                  <IconButton size="small" color="primary" onClick={() => handleEditAlert(alert)}>
                                    <EditIcon fontSize="small" />
                                  </IconButton>
                                  <IconButton size="small" color="error" onClick={() => handleDeleteAlert(alert.id)}>
                                    <DeleteIcon fontSize="small" />
                                  </IconButton>
                                </Box>
                              </TableCell>
                            </>
                          )}
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </div>
  );
};

export default TradingViewAlerts; 